/** Genel deneme sorusu (kart-sorulari KartSoru + kartId yönlendirme). */
export type GenelSoru = {
  id: string;
  /** Sorunun kanunu (seed law_id) — "ilgili kartı çalış" tahmin yapmasın diye. */
  lawId?: number;
  soru: string;
  siklar: string[];
  dogru: number;
  aciklama: string;
  kaynak: string;
  zorluk: string;
  /** Yanlış cevapta yönlendirilecek kart anahtarı (kullanılmıyor, uyumluluk için). */
  kartId: string;
};

export type GenelDeneme = {
  /** Deneme numarası. */
  no: number;
  /** Görünen başlık. */
  baslik: string;
  sorular: GenelSoru[];
};

